`timescale 1ns/1ps
// Lesson 12 testbench — a decoder tested against real instruction words.
//
// The vectors below are not made up. They are genuine RV32I encodings,
// generated by the small Python assembler shown in the README, and each is
// labelled with the assembly it came from. 45 of them, covering every
// instruction format and the awkward corners of each immediate.
//
// What is checked:
//   1. immgen reproduces the exact immediate for all 45, including the
//      sign-extended extremes of every format
//   2. the control signals are right per instruction class
//   3. `addi` with a NEGATIVE immediate asks the ALU for ADD, not SUB --
//      the trap described in decode.v
//   4. malformed instructions raise `illegal`, and well-formed ones do not
//
// Test 3 is the one that matters most. It is a one-bit mistake that makes
// every negative addi silently subtract, it is invisible in an R-type-only
// test, and it is the reason lesson 13's first program would otherwise
// compute nonsense.
module tb_decode;

localparam NV = 52;

    reg  [31:0] iv [0:NV-1];       // the instruction word
    reg  [31:0] ie [0:NV-1];       // the immediate it should produce
    reg  [31:0] inst = 0;

    wire [31:0] imm;
    immgen u_imm (.inst(inst), .imm(imm));

    wire [4:0] rs1, rs2, rd;
    wire       reg_we, alu_a_pc, alu_a_zero, alu_b_imm, mem_read, mem_write;
    wire [3:0] alu_op;
    wire [2:0] mem_op;
    wire       branch, jump, jalr, illegal;
    wire [1:0] wb_src;

    decode u_dec (
        .inst(inst), .rs1(rs1), .rs2(rs2), .rd(rd), .reg_we(reg_we),
        .alu_op(alu_op), .alu_a_pc(alu_a_pc), .alu_a_zero(alu_a_zero),
        .alu_b_imm(alu_b_imm),
        .mem_read(mem_read), .mem_write(mem_write), .mem_op(mem_op),
        .branch(branch), .jump(jump), .jalr(jalr),
        .wb_src(wb_src), .illegal(illegal));

    localparam [1:0] WB_ALU = 2'd0, WB_MEM = 2'd1, WB_PC4 = 2'd2;

    integer errors = 0, checks = 0;

    task expect(input [8*40-1:0] name, input [31:0] got, input [31:0] want);
    begin
        checks = checks + 1;
        if (got !== want) begin
            errors = errors + 1;
            if (errors <= 14)
                $display("  FAIL inst=%h  %0s = %h, expected %h",
                         inst, name, got, want);
        end
    end
    endtask

    integer i;

    initial begin
        $dumpfile("decode.vcd");
        $dumpvars(0, tb_decode);

        iv[ 0] = 32'h003100B3; ie[ 0] = 32'h00000000;  // add x1,x2,x3
        iv[ 1] = 32'h403100B3; ie[ 1] = 32'h00000000;  // sub x1,x2,x3
        iv[ 2] = 32'h003110B3; ie[ 2] = 32'h00000000;  // sll x1,x2,x3
        iv[ 3] = 32'h003120B3; ie[ 3] = 32'h00000000;  // slt x1,x2,x3
        iv[ 4] = 32'h003130B3; ie[ 4] = 32'h00000000;  // sltu x1,x2,x3
        iv[ 5] = 32'h003140B3; ie[ 5] = 32'h00000000;  // xor x1,x2,x3
        iv[ 6] = 32'h003150B3; ie[ 6] = 32'h00000000;  // srl x1,x2,x3
        iv[ 7] = 32'h403150B3; ie[ 7] = 32'h00000000;  // sra x1,x2,x3
        iv[ 8] = 32'h003160B3; ie[ 8] = 32'h00000000;  // or x1,x2,x3
        iv[ 9] = 32'h003170B3; ie[ 9] = 32'h00000000;  // and x1,x2,x3
        iv[10] = 32'h00510093; ie[10] = 32'h00000005;  // addi x1,x2,5
        iv[11] = 32'hFFF10093; ie[11] = 32'hFFFFFFFF;  // addi x1,x2,-1
        iv[12] = 32'h80010093; ie[12] = 32'hFFFFF800;  // addi x1,x2,-2048
        iv[13] = 32'h7FF10093; ie[13] = 32'h000007FF;  // addi x1,x2,2047
        iv[14] = 32'hFFB12093; ie[14] = 32'hFFFFFFFB;  // slti x1,x2,-5
        iv[15] = 32'hFFF14093; ie[15] = 32'hFFFFFFFF;  // xori x1,x2,-1
        iv[16] = 32'h00711093; ie[16] = 32'h00000007;  // slli x1,x2,7
        iv[17] = 32'h00715093; ie[17] = 32'h00000007;  // srli x1,x2,7
        iv[18] = 32'h40715093; ie[18] = 32'h00000407;  // srai x1,x2,7
        iv[19] = 32'h00810083; ie[19] = 32'h00000008;  // lb x1,8(x2)
        iv[20] = 32'h00811083; ie[20] = 32'h00000008;  // lh x1,8(x2)
        iv[21] = 32'h00812083; ie[21] = 32'h00000008;  // lw x1,8(x2)
        iv[22] = 32'h00814083; ie[22] = 32'h00000008;  // lbu x1,8(x2)
        iv[23] = 32'h00815083; ie[23] = 32'h00000008;  // lhu x1,8(x2)
        iv[24] = 32'hFFC12083; ie[24] = 32'hFFFFFFFC;  // lw x1,-4(x2)
        iv[25] = 32'h00310623; ie[25] = 32'h0000000C;  // sb x3,12(x2)
        iv[26] = 32'h00311623; ie[26] = 32'h0000000C;  // sh x3,12(x2)
        iv[27] = 32'h00312623; ie[27] = 32'h0000000C;  // sw x3,12(x2)
        iv[28] = 32'hFE312C23; ie[28] = 32'hFFFFFFF8;  // sw x3,-8(x2)
        iv[29] = 32'h00208863; ie[29] = 32'h00000010;  // beq x1,x2,+16
        iv[30] = 32'h00209863; ie[30] = 32'h00000010;  // bne x1,x2,+16
        iv[31] = 32'h0020C863; ie[31] = 32'h00000010;  // blt x1,x2,+16
        iv[32] = 32'h0020D863; ie[32] = 32'h00000010;  // bge x1,x2,+16
        iv[33] = 32'h0020E863; ie[33] = 32'h00000010;  // bltu x1,x2,+16
        iv[34] = 32'h0020F863; ie[34] = 32'h00000010;  // bgeu x1,x2,+16
        iv[35] = 32'hFE2088E3; ie[35] = 32'hFFFFFFF0;  // beq x1,x2,-16
        iv[36] = 32'h7E208FE3; ie[36] = 32'h00000FFE;  // beq x1,x2,+4094
        iv[37] = 32'h80208063; ie[37] = 32'hFFFFF000;  // beq x1,x2,-4096
        iv[38] = 32'h123450B7; ie[38] = 32'h12345000;  // lui x1,0x12345
        iv[39] = 32'hFFFFF0B7; ie[39] = 32'hFFFFF000;  // lui x1,0xFFFFF
        iv[40] = 32'h01000097; ie[40] = 32'h01000000;  // auipc x1,0x1000
        iv[41] = 32'h020000EF; ie[41] = 32'h00000020;  // jal x1,+32
        iv[42] = 32'hFF9FF06F; ie[42] = 32'hFFFFFFF8;  // jal x0,-8
        iv[43] = 32'h7FFFF0EF; ie[43] = 32'h000FFFFE;  // jal x1,+1048574
        iv[44] = 32'h010100E7; ie[44] = 32'h00000010;  // jalr x1,16(x2)
        // Odd and small offsets. ADDED AFTER A MUTATION SURVIVED: every
        // store offset above happens to be EVEN, so an immgen bug that
        // forced imm[0] to zero was completely invisible. Mutation testing
        // found the hole in the vectors, not in the design.
        iv[45] = 32'h003103A3; ie[45] = 32'h00000007;  // sb x3,7(x2)
        iv[46] = 32'hFE310CA3; ie[46] = 32'hFFFFFFF9;  // sb x3,-7(x2)
        iv[47] = 32'h00311123; ie[47] = 32'h00000002;  // sh x3,2(x2)
        iv[48] = 32'h00110083; ie[48] = 32'h00000001;  // lb x1,1(x2)
        iv[49] = 32'hFFF10083; ie[49] = 32'hFFFFFFFF;  // lb x1,-1(x2)
        iv[50] = 32'h00314083; ie[50] = 32'h00000003;  // lbu x1,3(x2)
        iv[51] = 32'h00110093; ie[51] = 32'h00000001;  // addi x1,x2,1

        // ===== 1. every immediate, from every format =======================
        for (i = 0; i < NV; i = i + 1) begin
            inst = iv[i]; #1;
            expect("imm", imm, ie[i]);
            // No well-formed instruction in the list may be flagged illegal.
            expect("illegal", {31'd0, illegal}, 32'd0);
        end

        // ===== 2. control signals, per class ===============================
        // R-type: reads two registers, writes one, no memory, no jump.
        inst = 32'h003100B3; #1;                         // add x1,x2,x3
        expect("rs1",       {27'd0, rs1},       32'd2);
        expect("rs2",       {27'd0, rs2},       32'd3);
        expect("rd",        {27'd0, rd},        32'd1);
        expect("reg_we",    {31'd0, reg_we},    32'd1);
        expect("alu_b_imm", {31'd0, alu_b_imm}, 32'd0);  // operand B is rs2
        expect("alu_op",    {28'd0, alu_op},    32'h0);  // ADD
        expect("mem_read",  {31'd0, mem_read},  32'd0);
        expect("wb_src",    {30'd0, wb_src},    {30'd0, WB_ALU});

        inst = 32'h403100B3; #1;                         // sub x1,x2,x3
        expect("alu_op SUB", {28'd0, alu_op}, 32'h8);

        // Load: reads one register, writes one, result comes from memory.
        inst = 32'h0081A083; #1;                         // lw x1,8(x3)
        expect("load reg_we",    {31'd0, reg_we},    32'd1);
        expect("load mem_read",  {31'd0, mem_read},  32'd1);
        expect("load alu_b_imm", {31'd0, alu_b_imm}, 32'd1);
        expect("load alu_op",    {28'd0, alu_op},    32'h0);   // address ADD
        expect("load wb_src",    {30'd0, wb_src},    {30'd0, WB_MEM});

        // Store: writes NO register.
        inst = 32'h00312623; #1;                         // sw x3,12(x2)
        expect("store reg_we",    {31'd0, reg_we},    32'd0);
        expect("store mem_write", {31'd0, mem_write}, 32'd1);
        expect("store alu_op",    {28'd0, alu_op},    32'h0);  // address ADD

        // Branch: writes no register, operand B is rs2 (they are compared).
        inst = 32'h00208863; #1;                         // beq x1,x2,+16
        expect("branch reg_we",    {31'd0, reg_we},    32'd0);
        expect("branch branch",    {31'd0, branch},    32'd1);
        expect("branch jump",      {31'd0, jump},      32'd0);
        expect("branch alu_b_imm", {31'd0, alu_b_imm}, 32'd0);

        // JAL: writes pc+4 into rd, operand A is the PC.
        inst = 32'h020000EF; #1;                         // jal x1,+32
        expect("jal reg_we",   {31'd0, reg_we},   32'd1);
        expect("jal jump",     {31'd0, jump},     32'd1);
        expect("jal jalr",     {31'd0, jalr},     32'd0);
        expect("jal alu_a_pc", {31'd0, alu_a_pc}, 32'd1);
        expect("jal wb_src",   {30'd0, wb_src},   {30'd0, WB_PC4});

        // JALR: same writeback, but the target comes from rs1.
        inst = 32'h010100E7; #1;                         // jalr x1,16(x2)
        expect("jalr jalr",     {31'd0, jalr},     32'd1);
        expect("jalr alu_a_pc", {31'd0, alu_a_pc}, 32'd0);
        expect("jalr wb_src",   {30'd0, wb_src},   {30'd0, WB_PC4});

        // LUI: the immediate passes through, so the ALU must ADD (to x0).
        inst = 32'h123450B7; #1;                         // lui x1,0x12345
        expect("lui alu_op", {28'd0, alu_op},    32'h0);
        expect("lui reg_we", {31'd0, reg_we},    32'd1);
        expect("lui b_imm",  {31'd0, alu_b_imm}, 32'd1);
        // Operand A must be ZERO, not rs1. LUI has no rs1 field: inst[19:15]
        // is part of its immediate, so reading a register there adds garbage.
        // This check was added after lesson 13's CPU stored X for every
        // large constant -- the decoder test had verified the ALU op and
        // never asked where the operands came from.
        expect("lui a_zero", {31'd0, alu_a_zero}, 32'd1);
        expect("lui a_pc",   {31'd0, alu_a_pc},   32'd0);

        // ...and nothing else forces operand A to zero.
        inst = 32'h003100B3; #1;                         // add x1,x2,x3
        expect("add a_zero",  {31'd0, alu_a_zero}, 32'd0);
        inst = 32'h01000097; #1;                         // auipc x1,0x1000
        expect("auipc a_zero", {31'd0, alu_a_zero}, 32'd0);

        // AUIPC: pc + immediate.
        inst = 32'h01000097; #1;                         // auipc x1,0x1000
        expect("auipc a_pc",  {31'd0, alu_a_pc},  32'd1);
        expect("auipc alu_op", {28'd0, alu_op},   32'h0);

        // ===== 3. THE TRAP: addi with a negative immediate =================
        // inst[30] is 1 whenever the immediate is large or negative, and for
        // OP-IMM it is part of the immediate, NOT the SUB selector.
        inst = 32'hFFF10093; #1;                         // addi x1,x2,-1
        expect("addi -1 alu_op", {28'd0, alu_op}, 32'h0);     // ADD, not SUB
        expect("addi -1 imm",    imm,             32'hFFFFFFFF);

        inst = 32'h80010093; #1;                         // addi x1,x2,-2048
        expect("addi -2048 alu_op", {28'd0, alu_op}, 32'h0);  // ADD

        // ...while SRAI genuinely does use inst[30].
        inst = 32'h40715093; #1;                         // srai x1,x2,7
        expect("srai alu_op", {28'd0, alu_op}, 32'hD);        // SRA = 1101
        inst = 32'h00715093; #1;                         // srli x1,x2,7
        expect("srli alu_op", {28'd0, alu_op}, 32'h5);        // SRL = 0101

        // And `xori x1,x2,-1` -- the idiom for bitwise NOT -- must be XOR.
        inst = 32'hFFF14093; #1;                         // xori x1,x2,-1
        expect("xori alu_op", {28'd0, alu_op}, 32'h4);        // XOR = 0100

        // ===== 4. illegal instructions =====================================
        inst = 32'h00000000; #1;                              // all zeros
        expect("zero illegal", {31'd0, illegal}, 32'd1);
        inst = 32'hFFFFFFFF; #1;                              // all ones
        expect("ones illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h0000007F; #1;                              // bad opcode
        expect("bad opcode illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h203100B3; #1;        // R-type, funct7 = 0010000
        expect("bad funct7 illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h0020A863; #1;        // branch, funct3 = 010
        expect("branch f3=010 illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h0020B863; #1;        // branch, funct3 = 011
        expect("branch f3=011 illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h0081B083; #1;        // load, funct3 = 011
        expect("load f3=011 illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h0081F083; #1;        // load, funct3 = 111
        expect("load f3=111 illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h00313623; #1;        // store, funct3 = 011
        expect("store f3=011 illegal", {31'd0, illegal}, 32'd1);
        inst = 32'h010110E7; #1;        // jalr, funct3 = 001
        expect("bad jalr illegal", {31'd0, illegal}, 32'd1);

        // And the contrast: neighbouring encodings that ARE legal must not be
        // flagged. A decoder that rejects everything would pass the tests
        // above, which is why these matter as much as those do.
        inst = 32'h0020C863; #1;        // blt x1,x2,+16  (funct3 = 100)
        expect("blt legal", {31'd0, illegal}, 32'd0);
        inst = 32'h403150B3; #1;        // sra x1,x2,x3   (funct7 = 0100000)
        expect("sra legal", {31'd0, illegal}, 32'd0);
        inst = 32'h0020D863; #1;        // bge x1,x2,+16  (funct3 = 101)
        expect("bge legal", {31'd0, illegal}, 32'd0);

        if (errors == 0)
            $display("PASS: %0d checks - 52 real instruction encodings decoded, every immediate format exact, negative addi asks for ADD not SUB, 8 malformed instructions flagged illegal", checks);
        else
            $display("FAIL: %0d of %0d checks wrong", errors, checks);
        $finish;
    end
endmodule
